    onDetaileeMenuClick: function (menu, item, e, eOpts) {
        var url = bcp.config.Runtime.getServerBaseUrl() + "users/detailee/clear",
            method = "POST";
        var groupId = item.groupId,
            groupName = item.groupName;

        if (!item.clearDetailee) {
            url = bcp.config.Runtime.getServerBaseUrl() + "users/detailee/set?groupId=" + groupId + "&";
        }

        Ext.Ajax.request({
            url: url,
            method: method,
            scope: this,
            success: function (response) {
                var msg = "";
                if (!item.clearDetailee) {
                    msg =
                        "You are swtiching to the Detailee Mode as a member for group " +
                        groupName +
                        "<br> The page will now reload.";
                } else {
                    msg = "You are exiting the Detailee Mode. <br> The page will now reload.";
                }
                Ext.Msg.alert("Success!", msg, function (btn) {
                    if (btn == "ok") {
                        window.onbeforeunload = null;
                        //clear caches to make sure after switching org when entering/exiting detailee mode
                        //the old cache data were cleared
                        if (navigator.serviceWorker) {
                            navigator.serviceWorker.getRegistration().then(function (registration) {
                                if (registration) {
                                    //console.log(registration.toString());
                                    registration
                                        .unregister()
                                        .then(function (success) {
                                            // if success = true, unregister was successful
                                            //console.log("service worker unregistered");
                                        })
                                        .then(function (cleanCache) {
                                            if ("caches" in window) {
                                                caches
                                                    .keys()
                                                    .then(function (keyList) {
                                                        return Promise.all(
                                                            keyList.map(function (key) {
                                                                //console.log(key);
                                                                return caches.delete(key);
                                                            })
                                                        );
                                                    })
                                                    .then(function (final) {
                                                        //debugger;
                                                        location.reload();
                                                    });
                                            }
                                        });
                                } else {
                                    location.reload();
                                }
                            });
                        } else {
                            window.location.reload();
                        }
                    }
                });
            },
            failure: function (response) {
                console.log("Detailee Mode failed!");
            }
        });
    },

